CREATE TABLE automation_draft_revisions(household_id TEXT NOT NULL REFERENCES households(household_id), rule_id TEXT NOT NULL, revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>=1), definition TEXT NOT NULL, PRIMARY KEY(household_id,rule_id,revision));
